+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected Veterinarians navigation link");
+        UI.getCurrent().navigate(link.getPath());
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+
+        GridTester<Grid<Vet>, Vet> tester = test(grid());
+        assertEquals(6, tester.size());
+        assertEquals("First Name", tester.getHeaderCell(0));
+        assertEquals("Last Name", tester.getHeaderCell(1));
+        assertEquals("Specialties", tester.getHeaderCell(2));
+        assertEquals(List.of("James|Carter|none", "Linda|Douglas|dentistry, surgery",
+                        "Sharon|Jenkins|none", "Helen|Leary|radiology",
+                        "Rafael|Ortega|surgery", "Henry|Stevens|radiology"),
+                java.util.stream.IntStream.range(0, tester.size())
