+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridRequestsBoundedPagesUntilEveryVetIsLoaded() {
+        for (int i = 0; i < 120; i++) {
+            // Identical names exercise the ID tie-breaker between pages.
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME).values("Additional", "Vet").execute();
+        }
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertInstanceOf(CallbackDataProvider.class, grid.getDataProvider());
+        clearInvocations(repository);
+
+        List<Vet> loaded = new ArrayList<>();
+        int total = grid.getDataProvider().size(new Query<>());
+        assertEquals(126, total);
+        for (int offset = 0; offset < total; offset += 17) {
+            List<Vet> page = grid.getDataProvider()
+                    .fetch(new Query<>(offset, 17, List.of(), null, null)).toList();
+            assertEquals(Math.min(17, total - offset), page.size());
+            verify(repository).findPage(offset, 17);
+            loaded.addAll(page);
+        }
+        assertEquals(total, loaded.stream().map(Vet::id).distinct().count());
+        assertEquals(repository.findPage(0, total).toList(), loaded);
+        assertTrue(grid.getDataProvider().fetch(new Query<>(total, 17, List.of(), null, null)).toList().isEmpty());
+    }
